318	/**
319	 * Solve the floating point adding problem like 0.1 + 0.2 === 0.30000000000000004
320	 * See <http://0.30000000000000004.com/>
321	 */
322	export function addSafe(val0: number, val1: number): number {
323	    const maxPrecision = Math.max(getPrecision(val0), getPrecision(val1));
324	    // const multiplier = Math.pow(10, maxPrecision);
325	    // return (Math.round(val0 * multiplier) + Math.round(val1 * multiplier)) / multiplier;
326	    const sum = val0 + val1;
327	    // // PENDING: support more?
328	    return maxPrecision > ROUND_SUPPORTED_PRECISION_MAX
329	        ? sum : round(sum, maxPrecision);
330	}
