354	/**
355	 * @param value valid type: number | string | Date, otherwise return `new Date(NaN)`
356	 *   These values can be accepted:
357	 *   + An instance of Date, represent a time in its own time zone.
358	 *   + Or string in a subset of ISO 8601, only including:
359	 *     + only year, month, date: '2012-03', '2012-03-01', '2012-03-01 05', '2012-03-01 05:06',
360	 *     + separated with T or space: '2012-03-01T12:22:33.123', '2012-03-01 12:22:33.123',
361	 *     + time zone: '2012-03-01T12:22:33Z', '2012-03-01T12:22:33+8000', '2012-03-01T12:22:33-05:00',
362	 *     all of which will be treated as local time if time zone is not specified
363	 *     (see <https://momentjs.com/>).
364	 *   + Or other string format, including (all of which will be treated as local time):
365	 *     '2012', '2012-3-1', '2012/3/1', '2012/03/01',
366	 *     '2009/6/12 2:00', '2009/6/12 2:05:08', '2009/6/12 2:05:08.123'
367	 *   + a timestamp, which represent a time in UTC.
368	 * @return date Never be null/undefined. If invalid, return `new Date(NaN)`.
369	 */
370	export function parseDate(value: unknown): Date {
371	    if (value instanceof Date) {
372	        return value;
373	    }
374	    else if (zrUtil.isString(value)) {
375	        // Different browsers parse date in different way, so we parse it manually.
376	        // Some other issues:
377	        // new Date('1970-01-01') is UTC,
378	        // new Date('1970/01/01') and new Date('1970-1-01') is local.
379	        // See issue #3623
380	        const match = TIME_REG.exec(value);
381	
382	        if (!match) {
383	            // return Invalid Date.
384	            return new Date(NaN);
385	        }
386	
387	        // Use local time when no timezone offset is specified.
388	        if (!match[8]) {
389	            // match[n] can only be string or undefined.
390	            // But take care of '12' + 1 => '121'.
391	            return new Date(
392	                +match[1],
393	                +(match[2] || 1) - 1,
394	                +match[3] || 1,
395	                +match[4] || 0,
396	                +(match[5] || 0),
397	                +match[6] || 0,
398	                match[7] ? +match[7].substring(0, 3) : 0
399	            );
400	        }
401	        // Timezoneoffset of Javascript Date has considered DST (Daylight Saving Time,
402	        // https://tc39.github.io/ecma262/#sec-daylight-saving-time-adjustment).
403	        // For example, system timezone is set as "Time Zone: America/Toronto",
404	        // then these code will get different result:
405	        // `new Date(1478411999999).getTimezoneOffset();  // get 240`
406	        // `new Date(1478412000000).getTimezoneOffset();  // get 300`
407	        // So we should not use `new Date`, but use `Date.UTC`.
408	        else {
409	            let hour = +match[4] || 0;
410	            if (match[8].toUpperCase() !== 'Z') {
411	                hour -= +match[8].slice(0, 3);
412	            }
413	            return new Date(Date.UTC(
414	                +match[1],
415	                +(match[2] || 1) - 1,
416	                +match[3] || 1,
417	                hour,
418	                +(match[5] || 0),
419	                +match[6] || 0,
420	                match[7] ? +match[7].substring(0, 3) : 0
421	            ));
422	        }
423	    }
424	    else if (value == null) {
425	        return new Date(NaN);
426	    }
427	
428	    return new Date(Math.round(value as number));
429	}
