431	/**
432	 * Quantity of a number. e.g. 0.1, 1, 10, 100
433	 *
434	 * @param val
435	 * @return
436	 */
437	export function quantity(val: number): number {
438	    return Math.pow(10, quantityExponent(val));
439	}
