441	/**
442	 * Exponent of the quantity of a number
443	 * e.g., 1234 equals to 1.234*10^3, so quantityExponent(1234) is 3
444	 *
445	 * @param val non-negative value
446	 * @return
447	 */
448	export function quantityExponent(val: number): number {
449	    if (val === 0) {
450	        return 0;
451	    }
452	
453	    let exp = Math.floor(Math.log(val) / Math.LN10);
454	    /**
455	     * exp is expected to be the rounded-down result of the base-10 log of val.
456	     * But due to the precision loss with Math.log(val), we need to restore it
457	     * using 10^exp to make sure we can get val back from exp. #11249
458	     */
459	    if (val / Math.pow(10, exp) >= 10) {
460	        exp++;
461	    }
462	    return exp;
463	}
