88	// FIXME 公用？
89	const bisect = function (
90	    a: [string | number, number][],
91	    x: number,
92	    lo: number,
93	    hi: number
94	): number {
95	    while (lo < hi) {
96	        const mid = lo + hi >>> 1;
97	        if (a[mid][1] < x) {
98	            lo = mid + 1;
99	        }
100	        else {
101	            hi = mid;
102	        }
103	    }
104	    return lo;
105	};
