113	class TimeScale extends IntervalScale<TimeScaleSetting> {
114	
115	    static type = 'time';
116	    readonly type = 'time';
117	
118	    private _approxInterval: number;
119	
120	    private _minLevelUnit: TimeUnit;
121	
122	    constructor(settings?: TimeScaleSetting) {
123	        super(settings);
124	    }
125	
126	    /**
127	     * Get label is mainly for other components like dataZoom, tooltip.
128	     */
129	    getLabel(tick: TimeScaleTick): string {
130	        const useUTC = this.getSetting('useUTC');
131	        return format(
132	            tick.value,
133	            fullLeveledFormatter[
134	                getDefaultFormatPrecisionOfInterval(getPrimaryTimeUnit(this._minLevelUnit))
135	            ] || fullLeveledFormatter.second,
136	            useUTC,
137	            this.getSetting('locale')
138	        );
139	    }
140	
141	    getFormattedLabel(
142	        tick: ScaleTick,
143	        idx: number,
144	        labelFormatter: TimeAxisLabelFormatterParsed
145	    ): string {
146	        const isUTC = this.getSetting('useUTC');
147	        const lang = this.getSetting('locale');
148	        return leveledFormat(tick, idx, labelFormatter, lang, isUTC);
149	    }
150	
151	    /**
152	     * @override
153	     */
154	    getTicks(opt?: ScaleGetTicksOpt): TimeScaleTick[] {
155	        opt = opt || {};
156	
157	        const interval = this._interval;
158	        const extent = this._extent;
159	        const scaleBreakHelper = getScaleBreakHelper();
160	
161	        let ticks = [] as TimeScaleTick[];
162	        // If interval is 0, return [];
163	        if (!interval) {
164	            return ticks;
165	        }
166	
167	        const useUTC = this.getSetting('useUTC');
168	
169	        if (scaleBreakHelper && opt.breakTicks === 'only_break') {
170	            getScaleBreakHelper().addBreaksToTicks(ticks, this._brkCtx!.breaks, this._extent);
171	            return ticks;
172	        }
173	
174	        const extent0Unit = getUnitFromValue(extent[1], useUTC);
175	        ticks.push({
176	            value: extent[0],
177	            time: {
178	                level: 0,
179	                upperTimeUnit: extent0Unit,
180	                lowerTimeUnit: extent0Unit,
181	            }
182	        });
183	
184	        const innerTicks = getIntervalTicks(
185	            this._minLevelUnit,
186	            this._approxInterval,
187	            useUTC,
188	            extent,
189	            this._getExtentSpanWithBreaks(),
190	            this._brkCtx
191	        );
192	
193	        ticks = ticks.concat(innerTicks);
194	
195	        const extent1Unit = getUnitFromValue(extent[1], useUTC);
196	        ticks.push({
197	            value: extent[1],
198	            time: {
199	                level: 0,
200	                upperTimeUnit: extent1Unit,
201	                lowerTimeUnit: extent1Unit,
202	            }
203	        });
204	
205	        const isUTC = this.getSetting('useUTC');
206	        let upperUnitIndex = primaryTimeUnits.length - 1;
207	        let maxLevel = 0;
208	        each(ticks, tick => {
209	            upperUnitIndex = Math.min(upperUnitIndex, indexOf(primaryTimeUnits, tick.time.upperTimeUnit));
210	            maxLevel = Math.max(maxLevel, tick.time.level);
211	        });
212	
213	        if (scaleBreakHelper) {
214	            getScaleBreakHelper().pruneTicksByBreak(
215	                opt.pruneByBreak,
216	                ticks,
217	                this._brkCtx!.breaks,
218	                item => item.value,
219	                this._approxInterval,
220	                this._extent
221	            );
222	        }
223	        if (scaleBreakHelper && opt.breakTicks !== 'none') {
224	            getScaleBreakHelper().addBreaksToTicks(ticks, this._brkCtx!.breaks, this._extent, trimmedBrk => {
225	                // @see `parseTimeAxisLabelFormatterDictionary`.
226	                const lowerBrkUnitIndex = Math.max(
227	                    indexOf(primaryTimeUnits, getUnitFromValue(trimmedBrk.vmin, isUTC)),
228	                    indexOf(primaryTimeUnits, getUnitFromValue(trimmedBrk.vmax, isUTC)),
229	                );
230	                let upperBrkUnitIndex = 0;
231	                for (let unitIdx = 0; unitIdx < primaryTimeUnits.length; unitIdx++) {
232	                    if (!isPrimaryUnitValueAndGreaterSame(
233	                        primaryTimeUnits[unitIdx], trimmedBrk.vmin, trimmedBrk.vmax, isUTC
234	                    )) {
235	                        upperBrkUnitIndex = unitIdx;
236	                        break;
237	                    }
238	                }
239	                const upperIdx = Math.min(upperBrkUnitIndex, upperUnitIndex);
240	                const lowerIdx = Math.max(upperIdx, lowerBrkUnitIndex);
241	                return {
242	                    level: maxLevel,
243	                    lowerTimeUnit: primaryTimeUnits[lowerIdx],
244	                    upperTimeUnit: primaryTimeUnits[upperIdx],
245	                };
246	            });
247	        }
248	
249	        return ticks;
250	    }
251	
252	    calcNiceExtent(
253	        opt?: {
254	            splitNumber?: number,
255	            fixMin?: boolean,
256	            fixMax?: boolean,
257	            minInterval?: number,
258	            maxInterval?: number
259	        }
260	    ): void {
261	        const extent = this.getExtent();
262	        // If extent start and end are same, expand them
263	        if (extent[0] === extent[1]) {
264	            // Expand extent
265	            extent[0] -= ONE_DAY;
266	            extent[1] += ONE_DAY;
267	        }
268	        // If there are no data and extent are [Infinity, -Infinity]
269	        if (extent[1] === -Infinity && extent[0] === Infinity) {
270	            const d = new Date();
271	            extent[1] = +new Date(d.getFullYear(), d.getMonth(), d.getDate());
272	            extent[0] = extent[1] - ONE_DAY;
273	        }
274	        this._innerSetExtent(extent[0], extent[1]);
275	
276	        this.calcNiceTicks(opt.splitNumber, opt.minInterval, opt.maxInterval);
277	    }
278	
279	    calcNiceTicks(approxTickNum: number, minInterval: number, maxInterval: number): void {
280	        approxTickNum = approxTickNum || 10;
281	
282	        const span = this._getExtentSpanWithBreaks();
283	        this._approxInterval = span / approxTickNum;
284	
285	        if (minInterval != null && this._approxInterval < minInterval) {
286	            this._approxInterval = minInterval;
287	        }
288	        if (maxInterval != null && this._approxInterval > maxInterval) {
289	            this._approxInterval = maxInterval;
290	        }
291	
292	        const scaleIntervalsLen = scaleIntervals.length;
293	        const idx = Math.min(
294	            bisect(scaleIntervals, this._approxInterval, 0, scaleIntervalsLen),
295	            scaleIntervalsLen - 1
296	        );
297	
298	        // Interval that can be used to calculate ticks
299	        this._interval = scaleIntervals[idx][1];
300	        // Min level used when picking ticks from top down.
301	        // We check one more level to avoid the ticks are to sparse in some case.
302	        this._minLevelUnit = scaleIntervals[Math.max(idx - 1, 0)][0];
303	    }
304	
305	    parse(val: number | string | Date): number {
306	        // val might be float.
307	        return isNumber(val) ? val : +numberUtil.parseDate(val);
308	    }
309	
310	    contain(val: number): boolean {
311	        return scaleHelper.contain(val, this._extent);
312	    }
313	
314	    normalize(val: number): number {
315	        return this._calculator.normalize(val, this._extent);
316	    }
317	
318	    scale(val: number): number {
319	        return this._calculator.scale(val, this._extent);
320	    }
321	
322	}
