451	function getDateInterval(approxInterval: number, daysInMonth: number) {
452	    approxInterval /= ONE_DAY;
453	    return approxInterval > 16 ? 16
454	                // Math.floor(daysInMonth / 2) + 1  // In this case we only want one tick between two months.
455	            : approxInterval > 7.5 ? 7  // TODO week 7 or day 8?
456	            : approxInterval > 3.5 ? 4
457	            : approxInterval > 1.5 ? 2 : 1;
458	}
459	
460	function getMonthInterval(approxInterval: number) {
461	    const APPROX_ONE_MONTH = 30 * ONE_DAY;
462	    approxInterval /= APPROX_ONE_MONTH;
463	    return approxInterval > 6 ? 6
464	            : approxInterval > 3 ? 3
465	            : approxInterval > 2 ? 2 : 1;
466	}
467	
468	function getHourInterval(approxInterval: number) {
469	    approxInterval /= ONE_HOUR;
470	    return approxInterval > 12 ? 12
471	            : approxInterval > 6 ? 6
472	            : approxInterval > 3.5 ? 4
473	            : approxInterval > 2 ? 2 : 1;
474	}
475	
476	function getMinutesAndSecondsInterval(approxInterval: number, isMinutes?: boolean) {
477	    approxInterval /= isMinutes ? ONE_MINUTE : ONE_SECOND;
478	    return approxInterval > 30 ? 30
479	            : approxInterval > 20 ? 20
480	            : approxInterval > 15 ? 15
481	            : approxInterval > 10 ? 10
482	            : approxInterval > 5 ? 5
483	            : approxInterval > 2 ? 2 : 1;
484	}
485	
486	function getMillisecondsInterval(approxInterval: number) {
487	    return numberUtil.nice(approxInterval, true);
488	}
