490	// e.g., if the input unit is 'day', start calculate ticks from the first day of
491	// that month to make ticks "nice".
492	function getFirstTimestampOfUnit(timestamp: number, unitName: TimeUnit, isUTC: boolean) {
493	    const upperUnitIdx = Math.max(0, indexOf(primaryTimeUnits, unitName) - 1);
494	    return roundTime(new Date(timestamp), primaryTimeUnits[upperUnitIdx], isUTC).getTime();
495	}
496	
497	function createEstimateNiceMultiple(
498	    setMethodName: JSDateSetterNames,
499	    dateMethodInterval: number,
500	) {
501	    const tmpDate = new Date(0);
502	    tmpDate[setMethodName](1);
503	    const tmpTime = tmpDate.getTime();
504	    tmpDate[setMethodName](1 + dateMethodInterval);
505	    const approxTimeInterval = tmpDate.getTime() - tmpTime;
506	
507	    return (tickVal: number, targetValue: number) => {
508	        // Only in month that accurate result can not get by division of
509	        // timestamp interval, but no need accurate here.
510	        return Math.max(
511	            0,
512	            Math.round((targetValue - tickVal) / approxTimeInterval)
513	        );
514	    };
515	}
516	
517	function getIntervalTicks(
518	    bottomUnitName: TimeUnit,
519	    approxInterval: number,
520	    isUTC: boolean,
521	    extent: number[],
522	    extentSpanWithBreaks: number,
523	    brkCtx: ScaleBreakContext | NullUndefined,
524	): TimeScaleTick[] {
525	    const safeLimit = 10000;
526	    const unitNames = timeUnits;
527	    // const bottomPrimaryUnitName = getPrimaryTimeUnit(bottomUnitName);
528	
529	    interface InnerTimeTick {
530	        value: TimeScaleTick['value']
531	        notAdd?: boolean
532	    }
533	
534	    let iter = 0;
535	
536	    function addTicksInSpan(
537	        interval: number,
538	        minTimestamp: number,
539	        maxTimestamp: number,
540	        getMethodName: JSDateGetterNames,
541	        setMethodName: JSDateSetterNames,
542	        isDate: boolean,
543	        out: InnerTimeTick[]
544	    ) {
545	        const estimateNiceMultiple = createEstimateNiceMultiple(setMethodName, interval);
546	
547	        let dateTime = minTimestamp;
548	        const date = new Date(dateTime);
549	
550	        // if (isDate) {
551	        //     d -= 1; // Starts with 0;   PENDING
552	        // }
553	
554	        while (dateTime < maxTimestamp && dateTime <= extent[1]) {
555	            out.push({
556	                value: dateTime
557	            });
558	
559	            if (iter++ > safeLimit) {
560	                if (__DEV__) {
561	                    warn('Exceed safe limit in time scale.');
562	                }
563	                break;
564	            }
565	
566	            date[setMethodName](date[getMethodName]() + interval);
567	            dateTime = date.getTime();
568	
569	            if (brkCtx) {
570	                const moreMultiple = brkCtx.calcNiceTickMultiple(dateTime, estimateNiceMultiple);
571	                if (moreMultiple > 0) {
572	                    date[setMethodName](date[getMethodName]() + moreMultiple * interval);
573	                    dateTime = date.getTime();
574	                }
575	            }
576	        }
577	
578	        // This extra tick is for calcuating ticks of next level. Will not been added to the final result
579	        out.push({
580	            value: dateTime,
581	            notAdd: true
582	        });
583	    }
584	
585	    function addLevelTicks(
586	        unitName: TimeUnit,
587	        lastLevelTicks: InnerTimeTick[],
588	        levelTicks: InnerTimeTick[]
589	    ) {
590	        const newAddedTicks: ScaleTick[] = [];
591	        const isFirstLevel = !lastLevelTicks.length;
592	
593	        if (isPrimaryUnitValueAndGreaterSame(getPrimaryTimeUnit(unitName), extent[0], extent[1], isUTC)) {
594	            return;
595	        }
596	
597	        if (isFirstLevel) {
598	            lastLevelTicks = [{
599	                value: getFirstTimestampOfUnit(extent[0], unitName, isUTC),
600	            }, {
601	                value: extent[1]
602	            }];
603	        }
604	
605	        for (let i = 0; i < lastLevelTicks.length - 1; i++) {
606	            const startTick = lastLevelTicks[i].value;
607	            const endTick = lastLevelTicks[i + 1].value;
608	            if (startTick === endTick) {
609	                continue;
610	            }
611	
612	            let interval: number;
613	            let getterName: JSDateGetterNames;
614	            let setterName: JSDateSetterNames;
615	            let isDate = false;
616	
617	            switch (unitName) {
618	                case 'year':
619	                    interval = Math.max(1, Math.round(approxInterval / ONE_DAY / 365));
620	                    getterName = fullYearGetterName(isUTC);
621	                    setterName = fullYearSetterName(isUTC);
622	                    break;
623	                case 'half-year':
624	                case 'quarter':
625	                case 'month':
626	                    interval = getMonthInterval(approxInterval);
627	                    getterName = monthGetterName(isUTC);
628	                    setterName = monthSetterName(isUTC);
629	                    break;
630	                case 'week':    // PENDING If week is added. Ignore day.
631	                case 'half-week':
632	                case 'day':
633	                    interval = getDateInterval(approxInterval, 31); // Use 32 days and let interval been 16
634	                    getterName = dateGetterName(isUTC);
635	                    setterName = dateSetterName(isUTC);
636	                    isDate = true;
637	                    break;
638	                case 'half-day':
639	                case 'quarter-day':
640	                case 'hour':
641	                    interval = getHourInterval(approxInterval);
642	                    getterName = hoursGetterName(isUTC);
643	                    setterName = hoursSetterName(isUTC);
644	                    break;
645	                case 'minute':
646	                    interval = getMinutesAndSecondsInterval(approxInterval, true);
647	                    getterName = minutesGetterName(isUTC);
648	                    setterName = minutesSetterName(isUTC);
649	                    break;
650	                case 'second':
651	                    interval = getMinutesAndSecondsInterval(approxInterval, false);
652	                    getterName = secondsGetterName(isUTC);
653	                    setterName = secondsSetterName(isUTC);
654	                    break;
655	                case 'millisecond':
656	                    interval = getMillisecondsInterval(approxInterval);
657	                    getterName = millisecondsGetterName(isUTC);
658	                    setterName = millisecondsSetterName(isUTC);
659	                    break;
660	            }
661	
662	            // Notice: This expansion by `getFirstTimestampOfUnit` may cause too many ticks and
663	            // iteration. e.g., when three levels of ticks is displayed, which can be caused by
664	            // data zoom and axis breaks. Thus trim them here.
665	            if (endTick >= extent[0] && startTick <= extent[1]) {
666	                addTicksInSpan(
667	                    interval, startTick, endTick, getterName, setterName, isDate, newAddedTicks
668	                );
669	            }
670	
671	            if (unitName === 'year' && levelTicks.length > 1 && i === 0) {
672	                // Add nearest years to the left extent.
673	                levelTicks.unshift({
674	                    value: levelTicks[0].value - interval
675	                });
676	            }
677	        }
678	
679	        for (let i = 0; i < newAddedTicks.length; i++) {
680	            levelTicks.push(newAddedTicks[i]);
681	        }
682	    }
683	
684	    const levelsTicks: InnerTimeTick[][] = [];
685	    let currentLevelTicks: InnerTimeTick[] = [];
686	
687	    let tickCount = 0;
688	    let lastLevelTickCount = 0;
689	    for (let i = 0; i < unitNames.length; ++i) {
690	        const primaryTimeUnit = getPrimaryTimeUnit(unitNames[i]);
691	        if (!isPrimaryTimeUnit(unitNames[i])) { // TODO
692	            continue;
693	        }
694	        addLevelTicks(unitNames[i], levelsTicks[levelsTicks.length - 1] || [], currentLevelTicks);
695	
696	        const nextPrimaryTimeUnit: PrimaryTimeUnit = unitNames[i + 1] ? getPrimaryTimeUnit(unitNames[i + 1]) : null;
697	        if (primaryTimeUnit !== nextPrimaryTimeUnit) {
698	            if (currentLevelTicks.length) {
699	                lastLevelTickCount = tickCount;
700	                // Remove the duplicate so the tick count can be precisely.
701	                currentLevelTicks.sort((a, b) => a.value - b.value);
702	                const levelTicksRemoveDuplicated = [];
703	                for (let i = 0; i < currentLevelTicks.length; ++i) {
704	                    const tickValue = currentLevelTicks[i].value;
705	                    if (i === 0 || currentLevelTicks[i - 1].value !== tickValue) {
706	                        levelTicksRemoveDuplicated.push(currentLevelTicks[i]);
707	                        if (tickValue >= extent[0] && tickValue <= extent[1]) {
708	                            tickCount++;
709	                        }
710	                    }
711	                }
712	
713	                const targetTickNum = extentSpanWithBreaks / approxInterval;
714	                // Added too much in this level and not too less in last level
715	                if (tickCount > targetTickNum * 1.5 && lastLevelTickCount > targetTickNum / 1.5) {
716	                    break;
717	                }
718	
719	                // Only treat primary time unit as one level.
720	                levelsTicks.push(levelTicksRemoveDuplicated);
721	
722	                if (tickCount > targetTickNum || bottomUnitName === unitNames[i]) {
723	                    break;
724	                }
725	
726	            }
727	            // Reset if next unitName is primary
728	            currentLevelTicks = [];
729	        }
730	
731	    }
732	
733	    const levelsTicksInExtent = filter(map(levelsTicks, levelTicks => {
734	        return filter(levelTicks, tick => tick.value >= extent[0] && tick.value <= extent[1] && !tick.notAdd);
735	    }), levelTicks => levelTicks.length > 0);
736	
737	    const ticks: TimeScaleTick[] = [];
738	    const maxLevel = levelsTicksInExtent.length - 1;
739	    for (let i = 0; i < levelsTicksInExtent.length; ++i) {
740	        const levelTicks = levelsTicksInExtent[i];
741	        for (let k = 0; k < levelTicks.length; ++k) {
742	            const unit = getUnitFromValue(levelTicks[k].value, isUTC);
743	            ticks.push({
744	                value: levelTicks[k].value,
745	                time: {
746	                    level: maxLevel - i,
747	                    upperTimeUnit: unit,
748	                    lowerTimeUnit: unit,
749	                },
750	            });
751	        }
752	    }
753	
754	    ticks.sort((a, b) => a.value - b.value);
755	    // Remove duplicates
756	    const result: TimeScaleTick[] = [];
757	    for (let i = 0; i < ticks.length; ++i) {
758	        if (i === 0 || ticks[i].value !== ticks[i - 1].value) {
759	            result.push(ticks[i]);
760	        }
761	    }
762	
763	    return result;
764	}
765	
