    createAxisLabels,
    createAxisLabelsComputingContext,
    AxisTickLabelComputingKind
} from '@/src/coord/axisTickLabelBuilder';

describe('time-axis-customvalues-formatter', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    it('time axis works with customValues and function formatter', function () {
        const weeklyData: [string, number][] = [
            ['2025-05-26', 116],
            ['2025-06-02', 129],
            ['2025-06-09', 135],
            ['2025-06-16', 86],
            ['2025-06-23', 73]
        ];
        const timestamps = weeklyData.map(d => +new Date(d[0]));

        const formatterCalls: number[] = [];
        chart.setOption({
            xAxis: {
                type: 'time',
                axisLabel: {
                    customValues: timestamps,
                    formatter: function (value: number) {
                        formatterCalls.push(value);
                        const date = new Date(value);
                        return 'W' + (date.getMonth() + 1) + '.' + date.getDate();
                    }
                }
            },
            yAxis: {
                type: 'value'
            },
            series: [{
                type: 'bar',
                data: weeklyData
            }]
        });

        const xAxis = getECModel(chart).getComponent('xAxis', 0) as CartesianAxisModel;
        const ctx = createAxisLabelsComputingContext(AxisTickLabelComputingKind.determine);
        let labels: ReturnType<typeof createAxisLabels>['labels'] = null;
        // Should not throw TypeError when tick has no `time` property.
        expect(function () {
            labels = createAxisLabels(xAxis.axis, ctx).labels;
        }).not.toThrow();

        expect(labels.length).toEqual(timestamps.length);
        // The formatter should have been called with the expected label values.
        expect(formatterCalls).toEqual(timestamps);
        expect(labels[0].formattedLabel).toEqual('W5.26');
