import { createChart, getECModel } from '../../test/ut/core/utHelper';
import { EChartsType } from '@/src/echarts';
import CartesianAxisModel from '@/src/coord/cartesian/AxisModel';

describe('cartesian-small-number-rounding', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    it('extreme small numbers can be displayed in Cartesian', function () {
        chart.setOption({
            xAxis: {
                type: 'category',
                data: ['a', 'b', 'c']
            },
            yAxis: {
                type: 'value'
            },
            series: [{
                type: 'line',
                data: [1e-15, 2e-15, 3e-15]
            }]
        });

        const yAxis = getECModel(chart).getComponent('yAxis', 0) as CartesianAxisModel;
        const scale = yAxis.axis.scale;

        const extent = scale.getExtent();
        // The extent must not be collapsed to [0, 0] by inappropriate rounding.
        expect(extent[1]).toBeGreaterThan(extent[0]);
        expect(extent[0]).toBeLessThanOrEqual(1e-15);
        expect(extent[1]).toBeGreaterThanOrEqual(3e-15);

        const ticks = scale.getTicks();
        expect(ticks.length).toBeGreaterThan(1);
        // Ticks must be strictly increasing, i.e. rounding must not destroy precision.
        for (let i = 1; i < ticks.length; i++) {
            expect(ticks[i].value).toBeGreaterThan(ticks[i - 1].value);
        }

        // Data points should map to distinct pixels and stay inside the extent.
        const coords = [1e-15, 2e-15, 3e-15].map(val => yAxis.axis.dataToCoord(val));
        expect(coords[0]).not.toEqual(coords[1]);
        expect(coords[1]).not.toEqual(coords[2]);
    });

    it('minor ticks of extreme small numbers keep precision', function () {
        chart.setOption({
            xAxis: {
                type: 'category',
                data: ['a', 'b', 'c']
            },
            yAxis: {
                type: 'value',
                minorTick: {
                    show: true
                }
            },
            series: [{
                type: 'line',
                data: [1e-15, 2e-15, 3e-15]
            }]
        });

        const yAxis = getECModel(chart).getComponent('yAxis', 0) as CartesianAxisModel;
        const scale = yAxis.axis.scale as import('@/src/scale/Interval').default;
        const minorTicks = scale.getMinorTicks(5);
        for (let i = 0; i < minorTicks.length; i++) {
            for (let j = 1; j < minorTicks[i].length; j++) {
                expect(minorTicks[i][j]).toBeGreaterThan(minorTicks[i][j - 1]);
            }
        }
    });

});

