import { createChart, getECModel } from '../../test/ut/core/utHelper';
import { EChartsType } from '@/src/echarts';
import CartesianAxisModel from '@/src/coord/cartesian/AxisModel';
import LogScale from '@/src/scale/Log';

describe('logscale-negative-exponent-rounding', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    function genData(exponent: number): [number, string][] {
        return [
            [0.00001782501876267492, `1.6783442046243093e${-9 + exponent}`],
            [0.20000000000000004, `1.5239855205892977e${-13 + exponent}`],
            [0.3097633237824966, `9.94535044331967e${-14 + exponent}`],
            [1, `2.966552224094815e${-19 + exponent}`]
        ];
    }

    function makeLogChart(exponent: number): LogScale {
        chart.setOption({
            xAxis: {},
            yAxis: {
                type: 'log',
                logBase: 10,
                axisLabel: {
                    formatter: function (value: number) {
                        return value.toExponential(0);
                    }
                }
            },
            series: [{
                type: 'line',
                data: genData(exponent)
            }]
        });
        const yAxis = getECModel(chart).getComponent('yAxis', 0) as CartesianAxisModel;
        return yAxis.axis.scale as LogScale;
    }

    it('log scale supports data with big negative exponent', function () {
        // Data magnitudes around 1e-59 .. 1e-69.
        const scale = makeLogChart(-50);

        const extent = scale.getExtent();
        expect(extent[0]).toBeGreaterThan(0);
        expect(extent[1]).toBeGreaterThan(extent[0]);
        expect(extent[0]).toBeLessThanOrEqual(2.966552224094815e-69);
        expect(extent[1]).toBeGreaterThanOrEqual(1.6783442046243093e-59);

        const ticks = scale.getTicks();
        expect(ticks.length).toBeGreaterThan(1);
        for (let i = 0; i < ticks.length; i++) {
            // Rounding must not collapse tiny powers to 0.
            expect(ticks[i].value).toBeGreaterThan(0);
            // Tick values should stay exact powers of the log base.
            expect(ticks[i].value).toEqual(Math.pow(10, Math.round(Math.log(ticks[i].value) / Math.LN10)));
            if (i > 0) {
                expect(ticks[i].value).toBeGreaterThan(ticks[i - 1].value);
            }
        }
    });

    it('log scale keeps moderate small values stable too', function () {
        const scale = makeLogChart(0);
        const ticks = scale.getTicks();
        expect(ticks.length).toBeGreaterThan(1);
        for (let i = 1; i < ticks.length; i++) {
            expect(ticks[i].value).toBeGreaterThan(ticks[i - 1].value);
        }
    });

});
